use std :: collections :: HashMap ; use std :: fs ; use std :: process :: Command ; use std :: path :: Path ; fn test_group_family_transitions () -> Result < () , String > { let transitions = vec ! [(0.9 , "Cyclic") , (1.9 , "Alternating") , (2.9 , "Lie Type") , (3.9 , "Sporadic") ,] ; for (complexity , expected_family) in transitions { let family = determine_group_family (complexity) ; assert_eq ! (family , expected_family) ; } println ! ("    ✓ Group family transitions test passed") ; Ok (()) }